"use client";
import { createContext, createElement, useContext, useEffect, useSyncExternalStore, } from "react";
import { FeatureFlags, } from "./mod.js";
export const FeatureFlagContext = createContext({
    featureFlags: new FeatureFlags({ schema: {} }),
    state: [{}, () => { }],
});
export function FeatureFlagProvider({ children, hydratedOverrides, ...options }) {
    const featureFlags = options.featureFlags ||
        new FeatureFlags(options.options);
    const jsonState = useSyncExternalStore((listener) => {
        featureFlags.subscribe(listener);
        return () => featureFlags.unsubscribe(listener);
    }, () => JSON.stringify(featureFlags.store), () => JSON.stringify(featureFlags.initialStore));
    const state = JSON.parse(jsonState);
    function setState(updates) {
        const flags = Object.keys(updates);
        flags.forEach((flag) => {
            const v = updates[flag];
            if (FeatureFlags.isValidValue(v)) {
                featureFlags.set(flag, v);
            }
        });
    }
    useEffect(() => {
        if (!hydratedOverrides)
            return;
        const flags = FeatureFlags.listOptionsFromSchema(featureFlags.schema);
        flags.forEach((flag) => {
            const override = hydratedOverrides(flag);
            if (FeatureFlags.isValidValue(override)) {
                try {
                    featureFlags.set(flag, override);
                }
                catch (_e) {
                    /* ignore readonly errors here */
                }
            }
        });
    }, []);
    return createElement(FeatureFlagContext.Provider, {
        value: {
            featureFlags,
            state: [state, setState],
        },
    }, children);
}
export function featureFlagsHookFactory(_) {
    return () => {
        const { state } = useContext(FeatureFlagContext);
        return state;
    };
}
